content:
Looking at this, I've built the complete game with pixel-sprite data, bezier-curve entry/dive paths, the full tractor-beam/dual-fighter state machine, challenging stages, and synthesized audio — all in one file.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>GALAGA</title>
<style>
  html,body{margin:0;padding:0;background:#000;height:100%;overflow:hidden}
  body{display:flex;align-items:center;justify-content:center}
  canvas{image-rendering:pixelated;image-rendering:crisp-edges;background:#000}
</style>
</head>
<body>
<canvas id="cv" width="224" height="288"></canvas>
<script>
'use strict';
/* ================= GALAGA clone - single file ================= */
const cv=document.getElementById('cv'), ctx=cv.getContext('2d');
const W=224,H=288,DT=1000/60;
ctx.imageSmoothingEnabled=false;
function resize(){ // integer scale, crisp pixels
  const s=Math.max(1,Math.min(Math.floor(innerWidth/W),Math.floor(innerHeight/H)));
  cv.style.width=(W*s)+'px'; cv.style.height=(H*s)+'px';
}
addEventListener('resize',resize); resize();

/* ---------------- utilities ---------------- */
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const pick=a=>a[(Math.random()*a.length)|0];
const P=(x,y)=>({x,y});
const mirr=a=>a.map(p=>({x:W-p.x,y:p.y}));
/* cubic bezier chain: pts length = 3n+1, t in [0,1] */
function pathPos(pts,t){
  t=clamp(t,0,1);
  const n=(pts.length-1)/3; let u=t*n;
  const i=Math.min(Math.floor(u),n-1); u-=i;
  const p0=pts[i*3],p1=pts[i*3+1],p2=pts[i*3+2],p3=pts[i*3+3],s=1-u;
  return {x:s*s*s*p0.x+3*s*s*u*p1.x+3*s*u*u*p2.x+u*u*u*p3.x,
          y:s*s*s*p0.y+3*s*s*u*p1.y+3*s*u*u*p2.y+u*u*u*p3.y};
}

/* ---------------- sprites (pixel data) ---------------- */
const SPR={
 player:[
 '......W......',
 '......W......',
 '.....WWW.....',
 '.....WRW.....',
 '.....WWW.....',
 '....WWWWW....',
 '....WWWWW....',
 '...WWWWWWW...',
 '...WWWWWWW...',
 '..WWWWWWWWW..',
 '.WWWWWWWWWWW.',
 '.WWWRWRWRWWW.',
 'WWWWWWWWWWWWW',
 'WWWWWRWRWWWWW',
 '.WWWWWWWWWWW.'],
 zakoA:[
 '..Y.....Y..',
 '..Y.BBB.Y..',
 '.YY.BBB.YY.',
 'Y.YBBBBBY.Y',
 '..BBBBBBB..',
 '..BWBRBBW..',
 '...RRRRR...',
 '....Y.Y....'],
 zakoB:[
 '...BBBBB...',
 '..BBBBBBB..',
 'Y.BBBBBBB.Y',
 'YY.BBBBB.YY',
 '.YYBBBBBYY.',
 '..BWBRBBW..',
 '...RRRRR...',
 '....Y.Y....'],
 goeiA:[
 '.W..RRRRR..W.',
 'WW.RRRRRRR.WW',
 'W.WRRWWWRRW.W',
 '..RRRRRRRRR..',
 '..RWRRRRRWR..',
 '...RRRRRRR...',
 '....RRRRR....',
 '.....RRR.....'],
 goeiB:[
 '....RRRRR....',
 '...RRRRRRR...',
 'WW.RRWWRWRRWW',
 'W.WRRRRRRRW.W',
 '.WWRRWWRWRRWW',
 '...RWRRRWR...',
 '....RRRRR....',
 '.....RRR.....'],
 bossA:[
 '..G.........G..',
 '..GG.......GG..',
 '...GG.GGG.GG...',
 '...GGGGGGGGG...',
 '.G.GGGGGGGGG.G.',
 'GG.GGWGGGWGG.GG',
 'G.GGGGGGGGGGG.G',
 'G.GGRRGGGRRGG.G',
 '..GGGGGGGGGGG..',
 '...GGRGGGRGG...',
 '....GGGGGGG....',
 '....GG.R.GG....',
 '.....G.R.G.....',
 '......RRR......',
 '.......R.......'],
 bossB:[
 '...............',
 '...GG.GGG.GG...',
 '....GGGGGGG....',
 '..GGGGGGGGGGG..',
 '.GGGGWGGGWGGGG.',
 '.GGGGGGGGGGGGG.',
 '..GRRGGGGGRRG..',
 '..GGGGGGGGGGG..',
 '...GGRGGGRGG...',
 '....GGGGGGG....',
 '....GG.R.GG....',
 '.....G.R.G.....',
 '......RRR......',
 '.......R.......',
 '...............'],
 flag:[
 'FFFFF',
 'FFFFF',
 'FFFFF',
 '.FFFF',
 '..FFF',
 '...FF',
 '....F']
};
const PAL={
 player:{W:'#ffffff',R:'#ff3030'},
 captive:{W:'#ff7040',R:'#ff2020'},   /* captured fighter turns red/orange */
 hostile:{W:'#ff7040',R:'#ff2020'},
 zako:{Y:'#ffd800',B:'#3860ff',W:'#ffffff',R:'#ff2020'},
 goei:{R:'#ff3030',W:'#ffffff'},
 boss:{G:'#28d028',W:'#ffffff',R:'#ff2020'},
 bossHit:{G:'#9048ff',W:'#ffffff',R:'#ff2020'}, /* damaged boss: blue/purple */
 flag:{F:'#ff2020'}
};
function drawSprite(name,x,y,pal){
  const rows=SPR[name];
  for(let r=0;r<rows.length;r++){const row=rows[r];
    for(let c=0;c<row.length;c++){const ch=row[c];
      if(ch==='.')continue;
      ctx.fillStyle=pal[ch]||'#fff';
      ctx.fillRect(x+c,y+r,1,1);}}
}
function txt(s,x,y,c,size,align){
  ctx.font='bold '+(size||8)+'px "Courier New",monospace';
  ctx.fillStyle=c||'#fff'; ctx.textAlign=align||'center'; ctx.textBaseline='top';
  ctx.fillText(s,x,y);
}

/* ---------------- audio (Web Audio, synthesized) ---------------- */
let AC=null,master=null;
function initAudio(){
  if(!AC){try{AC=new (window.AudioContext||window.webkitAudioContext)();
    master=AC.createGain(); master.gain.value=G.mute?0:0.3; master.connect(AC.destination);}catch(e){}}
  if(AC&&AC.state==='suspended')AC.resume();
}
function tone(type,f0,f1,t0,dur,vol){
  if(!AC)return; const t=AC.currentTime+t0;
  const o=AC.createOscillator(),g=AC.createGain();
  o.type=type; o.frequency.setValueAtTime(Math.max(1,f0),t);
  o.frequency.exponentialRampToValueAtTime(Math.max(1,f1),t+dur);
  g.gain.setValueAtTime(vol,t); g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  o.connect(g); g.connect(master); o.start(t); o.stop(t+dur+0.02);
}
function noiseBurst(t0,dur,vol,f0,f1){
  if(!AC)return; const t=AC.currentTime+t0, n=(AC.sampleRate*dur)|0;
  const buf=AC.createBuffer(1,n,AC.sampleRate), d=buf.getChannelData(0);
  for(let i=0;i<n;i++)d[i]=Math.random()*2-1;
  const s=AC.createBufferSource(); s.buffer=buf;
  const f=AC.createBiquadFilter(); f.type='lowpass';
  f.frequency.setValueAtTime(f0,t); f.frequency.exponentialRampToValueAtTime(Math.max(20,f1),t+dur);
  const g=AC.createGain(); g.gain.setValueAtTime(vol,t);
  g.gain.exponentialRampToValueAtTime(0.001,t+dur);
  s.connect(f); f.connect(g); g.connect(master); s.start(t);
}
function seq(notes,type,vol){ for(const[f,o,d]of notes)tone(type,f,f,o,d||0.11,vol); }
const sndShot     =()=>tone('square',900,240,0,0.09,0.22);
const sndExplode  =()=>{noiseBurst(0,0.25,0.4,1400,120);tone('triangle',320,60,0,0.2,0.18);};
const sndBossHit  =()=>tone('square',300,120,0,0.12,0.3);
const sndPExplode =()=>{noiseBurst(0,0.7,0.5,2200,60);tone('sawtooth',220,40,0,0.6,0.28);};
const sndCapture  =()=>tone('sine',700,120,0,1.1,0.3);
const sndJingle   =()=>seq([[523,0],[659,.13],[784,.26],[1047,.39],[784,.53],[1047,.65]],'square',0.2);
const sndExtra    =()=>seq([[784,0],[988,.1],[1175,.2],[1568,.3]],'square',0.22);
const sndDock     =()=>seq([[659,0],[880,.09],[1319,.18]],'square',0.22);
const sndBonus    =()=>seq([[1047,0],[1319,.08],[1568,.16],[2093,.24]],'square',0.2);
function sndBeam(){ /* wobbling tractor-beam tone */
  if(!AC)return; const t=AC.currentTime;
  const o=AC.createOscillator(),g=AC.createGain(),l=AC.createOscillator(),lg=AC.createGain();
  o.type='sawtooth'; o.frequency.value=180; l.type='sine'; l.frequency.value=11; lg.gain.value=70;
  l.connect(lg); lg.connect(o.frequency);
  g.gain.setValueAtTime(0.16,t); g.gain.exponentialRampToValueAtTime(0.001,t+2.2);
  o.connect(g); g.connect(master); o.start(t); l.start(t); o.stop(t+2.2); l.stop(t+2.2);
}

/* ---------------- starfield ---------------- */
const stars=[];
for(let i=0;i<70;i++)stars.push({x:Math.random()*W,y:Math.random()*H,
  s:0.15+Math.random()*0.6,c:['#ffffff','#ffd8a0','#a0c8ff','#a0ffa0','#ffffff'][i%5],p:Math.random()*6.28});
function updStars(){for(const s of stars){s.y+=s.s;if(s.y>=H){s.y=0;s.x=Math.random()*W;}}}
function drawStars(){
  for(const s of stars){
    ctx.globalAlpha=0.35+0.65*Math.abs(Math.sin(G.tick*0.05+s.p)); /* twinkle */
    ctx.fillStyle=s.c; ctx.fillRect(s.x|0,s.y|0,1,1);
  }
  ctx.globalAlpha=1;
}

/* ---------------- entry / challenge flight paths ---------------- */
const ENTRY=[
 [P(-20,160),P(70,170),P(150,90),P(100,45),P(55,60),P(70,160),P(190,175)],
 mirr([P(-20,160),P(70,170),P(150,90),P(100,45),P(55,60),P(70,160),P(190,175)]),
 [P(60,-20),P(60,80),P(170,150),P(175,60),P(170,-5),P(120,60),P(112,150)],
 mirr([P(60,-20),P(60,80),P(170,150),P(175,60),P(170,-5),P(120,60),P(112,150)]),
 [P(-20,230),P(90,250),P(190,210),P(170,130),P(150,60),P(80,50),P(70,120)]
];
const CHALP=[
 [P(-20,120),P(60,50),P(150,50),P(165,120),P(180,190),P(240,230),P(260,150)],
 [P(112,-20),P(40,50),P(180,90),P(70,140),P(150,190),P(90,250),P(112,310)],
 mirr([P(-20,120),P(60,50),P(150,50),P(165,120),P(180,190),P(240,230),P(260,150)]),
 [P(30,310),P(70,190),P(160,210),P(150,90),P(140,20),P(120,-10),P(112,-40)]
];

/* ---------------- game state ---------------- */
let hiStored=0; try{hiStored=+localStorage.getItem('galagaHi')||0;}catch(e){}
const G={
 state:'title', tick:0, stageTick:0, paused:false, mute:false,
 score:0, hi:hiStored, reserve:2, nextExtra:20000, stage:1,
 enemies:[], pShots:[], eBullets:[], explosions:[],
 freed:null, hostile:null, capturedBoss:null, captureBoss:null,
 player:{x:112,y:252,state:'normal',dual:false,inv:0,deathT:0,capT:0,capFrom:null},
 formT:0, diveT:120, fireT:120, readyMsg:0, introT:0, overT:0, resT:0,
 spawnQ:[], challenge:false, chal:null, groupId:0,
 stats:{shots:0,hits:0}
};
const keys={};

/* ---------------- flow control ---------------- */
function addScore(n){
  G.score+=n;
  if(G.score>G.hi){G.hi=G.score;try{localStorage.setItem('galagaHi',String(G.hi));}catch(e){}}
  while(G.score>=G.nextExtra){G.reserve++;sndExtra();G.nextExtra+=70000;} /* 20k then every 70k */
}
function startGame(){
  G.score=0;G.reserve=2;G.nextExtra=20000;G.stats={shots:0,hits:0};
  G.capturedBoss=null;G.captureBoss=null;G.freed=null;G.hostile=null;
  G.pShots=[];G.eBullets=[];G.explosions=[];
  resetPlayer(); beginStage(1);
}
function beginStage(n){
  G.stage=n;G.enemies=[];G.spawnQ=[];G.stageTick=0;G.diveT=140;G.fireT=140;
  G.capturedBoss=null;G.captureBoss=null;G.freed=null;G.hostile=null;
  G.pShots=[];G.eBullets=[];
  G.challenge=(n>=3&&(n-3)%4===0);
  G.chal={hits:0,bonus:0,counts:[0,0,0,0,0],died:[0,0,0,0,0],done:0};
  if(G.challenge)buildChallenge();else buildFormation();
  G.spawnQ.sort((a,b)=>a.t-b.t);
  if(G.player.state==='dead')resetPlayer();
  G.state='stageIntro';G.introT=130;sndJingle();
}
function buildFormation(){
  /* 4 boss (top), 8+8 goei, 10+10 zako = 40, entering in 5 groups on curved paths */
  const rows=[
    {type:'zako',y:104,cols:10,path:ENTRY[0]},
    {type:'zako',y:88, cols:10,path:ENTRY[1]},
    {type:'goei',y:72, cols:8, path:ENTRY[2]},
    {type:'goei',y:56, cols:8, path:ENTRY[3]},
    {type:'boss',y:40, cols:4, path:ENTRY[4]}
  ];
  rows.forEach((r,g)=>{
    const start=10-r.cols; // centre the row
    for(let i=0;i<r.cols;i++){
      const slot={x:22+(start+i)*20,y:r.y}, path=r.path, t=g*160+i*7;
      G.spawnQ.push({t,fn(){G.enemies.push({
        type:r.type,slot,pos:{x:path[0].x,y:path[0].y},state:'entry',
        path,t:0,speed:0.0075,hp:r.type==='boss'?2:1,captive:false,
        aT:(Math.random()*50)|0});}});
    }
  });
}
function buildChallenge(){
  /* 5 waves of 8 fly through on loops; no firing, no staying */
  const types=['zako','goei','zako','zako','goei','zako','goei','boss'];
  for(let w=0;w<5;w++){
    const path=CHALP[w%4];
    for(let i=0;i<8;i++){
      const t=w*170+i*10, type=types[i];
      G.spawnQ.push({t,fn(){G.enemies.push({
        type,slot:{x:0,y:0},pos:{x:path[0].x,y:path[0].y},state:'entry',
        path,t:0,speed:0.0075,hp:type==='boss'?2:1,wave:w,chal:true,aT:0});}});
    }
  }
}
function resetPlayer(){
  const p=G.player; p.x=112;p.dual=false;p.state='normal';p.inv=130;p.capT=0;
}
function shipLost(explode){
  const p=G.player;
  if(explode){addExplosion(p.x,p.y,true);sndPExplode();}
  p.state='dead';p.deathT=110;G.reserve--;
}
function hitPlayer(side){
  const p=G.player;
  if(p.dual){ /* only the struck half is lost */
    p.dual=false; addExplosion(p.x+(side||8),p.y,false); sndPExplode(); p.inv=100;
  } else shipLost(true);
}

/* ---------------- formation helpers ---------------- */
function slotPos(e){
  const sway=Math.sin(G.formT*0.012)*(G.allHome?4:8);
  const sc=G.allHome?1+0.06*Math.sin(G.formT*0.02):1; /* breathing once complete */
  return {x:112+(e.slot.x-112)*sc+sway, y:e.slot.y};
}
function divePath(e,dir){
  const s={x:e.pos.x,y:e.pos.y}, px=G.player.x;
  return [s,
    {x:s.x+dir*45,y:s.y+25},{x:s.x-dir*55,y:s.y+70},{x:s.x-dir*5,y:s.y+110},
    {x:s.x+dir*50,y:s.y+150},
    {x:clamp(px+(Math.random()*80-40),16,208),y:s.y+195},
    {x:clamp(px,16,208),y:H+30}];
}
function makeReturn(e){ /* re-enter from the top and fly back to the slot */
  const sl=slotPos(e), dir=Math.random()<.5?-1:1;
  e.rpath=[{x:clamp(sl.x+dir*60,10,214),y:-18},{x:clamp(sl.x+dir*30,10,214),y:24},
           {x:sl.x+dir*12,y:sl.y+26},{x:sl.x,y:sl.y}];
  e.t=0;
}
function fireAt(x,y){
  const p=G.player,dx=p.x-x,dy=p.y-y,d=Math.hypot(dx,dy)||1;
  const sp=2.1+Math.min(1.2,G.stage*0.08);
  G.eBullets.push({x,y,vx:dx/d*sp,vy:dy/d*sp});
}
function setDive(e,path,t,dir){
  e.state='dive';e.path=path;e.t=t;e.dir=dir;
  e.speed=0.010+G.stage*0.0004+Math.random()*0.002;
  e.fireT=20+Math.random()*50;
}
function launchDive(){
  const cand=G.enemies.filter(e=>e.state==='formation');
  if(!cand.length)return;
  /* occasional tractor-beam attempt by a boss */
  if(!G.capturedBoss&&G.player.state==='normal'&&!G.freed&&Math.random()<0.35){
    const bosses=cand.filter(e=>e.type==='boss'&&!e.captive&&
      !G.enemies.some(b=>b.state==='tractor'));
    if(bosses.length){startTractor(pick(bosses));return;}
  }
  const e=pick(cand), dir=Math.random()<0.5?-1:1;
  G.groupId++;
  const path=divePath(e,dir);
  setDive(e,path,0,dir); e.group=G.groupId;
  /* escorts peel off with the leader; bosses take goei escorts */
  let nEsc=G.stage>=2?(Math.random()<0.55?(Math.random()<0.4?2:1):0):(Math.random()<0.3?1:0);
  const pool=e.type==='boss'
    ? cand.filter(o=>o.type==='goei'&&o.state==='formation')
    : cand.filter(o=>o!==e&&o.type===e.type&&o.state==='formation');
  for(let i=0;i<nEsc&&pool.length;i++){
    const s=pick(pool); pool.splice(pool.indexOf(s),1);
    setDive(s,path,-(i+1)*0.07,dir); s.group=G.groupId;
  }
}
function startTractor(e){
  const tx=clamp(G.player.x,40,184);
  e.path=[{x:e.pos.x,y:e.pos.y},
          {x:e.pos.x+(e.pos.x<tx?-50:50),y:e.pos.y+40},
          {x:tx+(tx<e.pos.x?60:-60),y:70},
          {x:tx,y:96}];
  e.state='dive';e.t=0;e.tractor=true;e.beamT=0;e.speed=0.012;e.dir=1;
}

/* ---------------- combat ---------------- */
function fire(){
  if(G.readyMsg>0||G.player.state!=='normal')return;
  const p=G.player;
  if(p.dual){ /* dual fighter: two shots at once */
    if(G.pShots.length>2)return;
    G.pShots.push({x:p.x-8,y:p.y-8});G.pShots.push({x:p.x+8,y:p.y-8});
    G.stats.shots+=2;
  }else{
    if(G.pShots.length>1)return; /* max 2 player shots on screen */
    G.pShots.push({x:p.x,y:p.y-8}); G.stats.shots++;
  }
  sndShot();
}
function addExplosion(x,y,big){
  const a=[],r=[];
  for(let i=0;i<12;i++){a.push(Math.random()*6.283);r.push(Math.random());}
  G.explosions.push({x,y,t:0,a,r,big});
}
function hitEnemy(e){ /* a player shot connected */
  if(e.hp>1){e.hp--;sndBossHit();return;} /* boss galaga takes two hits */
  const idx=G.enemies.indexOf(e); if(idx>=0)G.enemies.splice(idx,1);
  addExplosion(e.pos.x,e.pos.y,false); sndExplode();
  let sc;
  if(G.challenge){sc=100;G.chal.hits++;G.chal.died[e.wave]++;}
  else if(e.type==='zako')sc=(e.state==='dive'||e.state==='tractor')?100:50;
  else if(e.type==='goei')sc=(e.state==='dive'||e.state==='tractor')?160:80;
  else{ /* boss */
    if(e.state==='tractor')sc=800;
    else if(e.state==='dive'){
      const n=G.enemies.filter(o=>o.group===e.group&&o.state==='dive').length;
      sc=n>=2?1600:n===1?800:400; /* escort count decides the value */
    } else sc=150;
    if(e.captive){
      G.capturedBoss=null;
      if(e.state==='dive'||e.state==='tractor'){
        G.freed={x:e.pos.x,y:e.pos.y-14,t:0};          /* freed: flies down and docks */
      } else {
        G.hostile={x:e.pos.x,y:e.pos.y-14,t:0,f:0};    /* shot in formation: captive turns hostile */
      }
    }
    if(G.captureBoss===e&&G.player.state==='captured')shipLost(true);
  }
  if(G.challenge){
    G.chal.counts[e.wave]++;
    if(G.chal.counts[e.wave]===8){
      if(G.chal.died[e.wave]===8){G.chal.bonus+=1000;addScore(1000);sndBonus();}
      G.chal.done++;
      if(G.chal.done===5){
        if(G.chal.hits===40){G.chal.bonus+=10000;addScore(10000);sndBonus();}
        G.state='chalResult';G.resT=260;
      }
    }
  }
  addScore(sc);
}
function beamCheck(e){ /* is the player inside the tractor cone? */
  const p=G.player;
  if(p.state==='normal'&&!p.dual&&p.inv<=0&&p.y>e.pos.y){
    const hw=3+(p.y-e.pos.y)*0.16;
    if(Math.abs(p.x-e.pos.x)<hw){
      p.state='captured';p.capT=0;p.capFrom={x:p.x,y:p.y};
      G.captureBoss=e;sndCapture();
    }
  }
}

/* ---------------- per-entity updates ---------------- */
function updEnemy(e){
  e.aT++;
  switch(e.state){
    case 'entry':
      e.t+=e.speed;
      if(e.t>=1){
        if(e.chal){ /* challenge flyers leave the screen */
          const i=G.enemies.indexOf(e);if(i>=0)G.enemies.splice(i,1);
          G.chal.counts[e.wave]++;
          if(G.chal.counts[e.wave]===8){
            if(G.chal.died[e.wave]===8){G.chal.bonus+=1000;addScore(1000);sndBonus();}
            G.chal.done++;
            if(G.chal.done===5){
              if(G.chal.hits===40){G.chal.bonus+=10000;addScore(10000);sndBonus();}
              G.state='chalResult';G.resT=260;
            }
          }
        } else e.state='toSlot';
      } else e.pos=pathPos(e.path,e.t);
      break;
    case 'toSlot':{
      const s=slotPos(e);
      e.pos.x+=(s.x-e.pos.x)*0.1; e.pos.y+=(s.y-e.pos.y)*0.1;
      if(Math.hypot(s.x-e.pos.x,s.y-e.pos.y)<1.5)e.state='formation';
      break;}
    case 'formation': e.pos=slotPos(e); break;
    case 'dive':{
      if(e.t<0){e.t+=e.speed;e.pos=slotPos(e);}
      else{e.t+=e.speed;e.pos=pathPos(e.path,e.t);}
      e.fireT--;
      if(e.fireT<=0&&e.t>0.05&&e.t<0.9&&G.readyMsg<=0&&!G.challenge){
        fireAt(e.pos.x,e.pos.y+6);
        e.fireT=30+Math.random()*Math.max(30,90-G.stage*4);
      }
      if(e.tractor&&e.t>=1){e.state='tractor';e.beamT=0;}
      else if(!e.tractor&&e.pos.y>H+18){e.state='return';makeReturn(e);}
      if(e.captive){ /* captured fighter shoots while its boss dives */
        e.capFire=(e.capFire||0)+1;
        if(e.capFire>80&&!G.challenge){e.capFire=0;fireAt(e.pos.x,e.pos.y-20);}
      }
      break;}
    case 'tractor':
      e.beamT++;
      if(e.beamT===25)sndBeam();
      if(e.beamT>25&&e.beamT<140)beamCheck(e);
      if(e.captive&&e.beamT%70===0)fireAt(e.pos.x,e.pos.y-20);
      if(e.beamT>=160){e.state='toSlot';e.tractor=false;}
      break;
    case 'return':
      e.t+=0.02; e.pos=pathPos(e.rpath,e.t);
      if(e.t>=1)e.state='formation';
      break;
  }
}
function updPlayer(){
  const p=G.player;
  if(p.inv>0)p.inv--;
  switch(p.state){
    case 'normal':
      if(G.readyMsg<=0){
        if(keys['arrowleft']||keys['a'])p.x-=2.2;
        if(keys['arrowright']||keys['d'])p.x+=2.2;
        p.x=clamp(p.x,10,W-10);
      }
      break;
    case 'captured':{ /* being pulled up: turns red, joins the formation */
      const e=G.captureBoss;
      if(!e||G.enemies.indexOf(e)<0){shipLost(true);break;}
      p.capT+=1/70;
      const u=p.capT*p.capT*(3-2*p.capT);
      p.x=p.capFrom.x+(e.pos.x-p.capFrom.x)*u;
      p.y=p.capFrom.y+(e.pos.y-14-p.capFrom.y)*u;
      if(p.capT>=1){e.captive=true;G.capturedBoss=e;shipLost(false);}
      break;}
    case 'dead':
      if(--p.deathT<=0){
        if(G.reserve<0){G.state='gameover';G.overT=150;}
        else {resetPlayer();G.readyMsg=90;} /* respawn with READY */
      }
      break;
  }
}
function updFreed(){
  const f=G.freed,p=G.player;
  f.t++; f.y+=1.6; f.x+=clamp(p.x+14-f.x,-1.2,1.2);
  if(p.state==='normal'&&f.y>=p.y-16&&Math.abs(f.x-(p.x+14))<6){
    p.dual=true;sndDock();G.freed=null; /* dock to form the dual fighter */
  }
  if(f&&f.y>H+20)G.freed=null;
}
function updHostile(){
  const h=G.hostile;
  h.t++; h.y+=1.8; h.x+=Math.sin(h.t*0.05)*1.5;
  h.f++; if(h.f>60&&!G.challenge){h.f=0;fireAt(h.x,h.y);}
  if(h.y>H+16)G.hostile=null; /* does not return */
}

/* ---------------- main update ---------------- */
function update(){
  G.tick++; updStars();
  for(const e of G.explosions)e.t++;
  G.explosions=G.explosions.filter(e=>e.t<25);
  switch(G.state){
    case 'stageIntro': if(--G.introT<=0){G.state='play';G.readyMsg=90;} break;
    case 'chalResult': if(--G.resT<=0)beginStage(G.stage+1); break;
    case 'gameover':   if(--G.overT<=0){G.state='results';G.resT=330;} break;
    case 'results':    if(--G.resT<=0)G.state='title'; break;
    case 'play': updatePlay(); break;
  }
}
function updatePlay(){
  G.stageTick++;
  while(G.spawnQ.length&&G.spawnQ[0].t<=G.stageTick)G.spawnQ.shift().fn();
  if(G.readyMsg>0)G.readyMsg--;
  G.formT++;
  updPlayer();
  for(const e of [...G.enemies])updEnemy(e);
  if(G.freed)updFreed();
  if(G.hostile)updHostile();

  G.entering=G.spawnQ.length>0||G.enemies.some(e=>e.state==='entry'||e.state==='toSlot');
  G.allHome=!G.challenge&&G.spawnQ.length===0&&G.enemies.length>0&&
             G.enemies.every(e=>e.state==='formation');

  /* schedule dives - more frequent/aggressive in later stages, never while respawning */
  if(!G.challenge&&!G.entering&&G.player.state==='normal'&&G.readyMsg<=0){
    G.diveT--;
    if(G.diveT<=0){launchDive();G.diveT=Math.max(40,160-G.stage*10)+Math.random()*50;}
  }
  /* formation / entry firing */
  if(!G.challenge&&G.player.state==='normal'&&G.readyMsg<=0){
    G.fireT--;
    if(G.fireT<=0){
      const pool=G.enemies.filter(e=>e.state==='formation'||e.state==='entry');
      if(pool.length){const e=pick(pool);fireAt(e.pos.x,e.pos.y+6);}
      G.fireT=Math.max(35,130-G.stage*7)+Math.random()*60;
    }
  }
  /* player shots */
  for(const b of G.pShots)b.y-=6;
  /* player shots vs enemies / hostile captive */
  for(const b of G.pShots){
    for(const e of G.enemies){
      const hw=e.type==='boss'?7:5;
      if(Math.abs(b.x-e.pos.x)<hw+1&&Math.abs(b.y-e.pos.y)<hw+2){
        b.dead=true;G.stats.hits++;hitEnemy(e);break;
      }
    }
    if(!b.dead&&G.hostile&&Math.abs(b.x-G.hostile.x)<6&&Math.abs(b.y-G.hostile.y)<7){
      b.dead=true;G.stats.hits++;addScore(100);
      addExplosion(G.hostile.x,G.hostile.y,false);sndExplode();G.hostile=null;
    }
  }
  G.pShots=G.pShots.filter(b=>!b.dead&&b.y>-10);
  /* enemy bullets */
  for(const b of G.eBullets){b.x+=b.vx;b.y+=b.vy;}
  const p=G.player;
  if(p.state==='normal'&&p.inv<=0){
    for(const b of G.eBullets){
      const dy=Math.abs(b.y-p.y)<8;
      let side=0;
      if(p.dual){
        if(dy&&Math.abs(b.x-(p.x-8))<5)side=-8;
        else if(dy&&Math.abs(b.x-(p.x+8))<5)side=8;
      } else if(dy&&Math.abs(b.x-p.x)<5)side=1;
      if(side){b.dead=true;hitPlayer(side===1?0:side);break;}
    }
  }
  G.eBullets=G.eBullets.filter(b=>!b.dead&&b.y<H+10&&b.y>-10&&b.x>-10&&b.x<W+10);
  /* enemy ramming the player: both destroyed (challenge flyers can't hurt you) */
  if(p.state==='normal'&&p.inv<=0&&!G.challenge){
    for(const e of G.enemies){
      if(e.state==='entry')continue;
      const hw=(e.type==='boss'?7:5)+4;
      let side=0;
      if(Math.abs(e.pos.y-p.y)<12){
        if(p.dual){
          if(Math.abs(e.pos.x-(p.x-8))<hw)side=-8;
          else if(Math.abs(e.pos.x-(p.x+8))<hw)side=8;
        } else if(Math.abs(e.pos.x-p.x)<hw)side=1;
      }
      if(side){
        if(e.hp>1){e.hp--;sndBossHit();}
        else{addExplosion(e.pos.x,e.pos.y,false);sndExplode();
             G.enemies.splice(G.enemies.indexOf(e),1);
             if(e.captive){G.capturedBoss=null;
               G.hostile={x:e.pos.x,y:e.pos.y-14,t:0,f:0};}}
        hitPlayer(side===1?0:side);
        break;
      }
    }
  }
  /* stage cleared */
  if(G.enemies.length===0&&G.spawnQ.length===0&&!G.chal.done&&
     G.player.state==='normal'&&!G.freed&&!G.hostile&&!G.challenge){
    beginStage(G.stage+1);
  }
}

/* ---------------- rendering ---------------- */
function drawEnemy(e){
  const fast=(e.state==='dive'||e.state==='tractor');
  const fr=Math.floor(e.aT/(fast?5:13))%2;
  let name,pal;
  if(e.type==='zako'){name=fr?'zakoB':'zakoA';pal=PAL.zako;}
  else if(e.type==='goei'){name=fr?'goeiB':'goeiA';pal=PAL.goei;}
  else{name=fr?'bossB':'bossA';pal=e.hp<2?PAL.bossHit:PAL.boss;}
  const rows=SPR[name],w=rows[0].length,h=rows.length;
  const x=Math.round(e.pos.x-w/2),y=Math.round(e.pos.y-h/2);
  drawSprite(name,x,y,pal);
  if(e.captive)drawSprite('player',Math.round(e.pos.x-6),y-15,PAL.captive);
}
function drawBeam(b){
  const top=b.pos.y+6,bot=H-18,t=b.beamT;
  const grow=Math.min(1,(t-15)/25), fade=t>140?(160-t)/20:1;
  const maxHw=22*grow*fade;
  ctx.globalAlpha=0.75*fade;
  for(let y=top;y<bot;y+=3){
    const f=(y-top)/(bot-top), hw=2+(maxHw-2)*f;
    const band=Math.floor((y+G.tick*1.5)/3)%3;
    ctx.fillStyle=band===0?'#40a0ff':band===1?'#a0e0ff':'#2060ff';
    ctx.fillRect(Math.round(b.pos.x-hw),y,Math.round(hw*2),2);
  }
  ctx.globalAlpha=1;
}
function drawExplosion(e){
  const f=Math.min(4,(e.t/5)|0);
  const cols=[['#ffffff','#ffd800'],['#ffd800','#ff8000'],['#ff8000','#ff2020'],
              ['#ff2020','#801010'],['#601010','#300000']][f];
  const R=(2+f*3)*(e.big?1.3:1);
  for(let i=0;i<e.a.length;i++){
    const d=R*(0.5+e.r[i]*0.8);
    const px=Math.round(e.x+Math.cos(e.a[i])*d),py=Math.round(e.y+Math.sin(e.a[i])*d);
    ctx.fillStyle=cols[i%2];
    ctx.fillRect(px,py,f<2?1:2,f<2?1:2);
  }
  if(f<2){ctx.fillStyle='#fff';ctx.fillRect(e.x-1,e.y-1,3,3);}
}
function drawPlayer(){
  const p=G.player;
  if(p.state!=='normal'&&p.state!=='captured')return;
  if(p.inv>0&&Math.floor(G.tick/4)%2)return;
  const pal=p.state==='captured'?PAL.captive:PAL.player;
  if(p.dual){
    drawSprite('player',p.x-6-8,p.y-7,PAL.player);
    drawSprite('player',p.x-6+8,p.y-7,PAL.player);
  } else drawSprite('player',p.x-6,p.y-7,pal);
}
function flagIcons(n){
  let v=1; for(const d of[5,10,20,30,50])if(n>=d)v=d;
  return {v,n:Math.round(n/v)};
}
function drawHUD(){
  txt('1UP',20,6,'#ffffff',8,'left');
  txt(String(G.score),20,15,'#ffffff',8,'left');
  txt('HIGH SCORE',112,6,'#ffffff');
  txt(String(Math.max(G.hi,G.score)),112,15,'#ffffff');
  for(let i=0;i<G.reserve;i++)drawSprite('player',6+i*15,271,PAL.player);
  const f=flagIcons(G.stage);
  for(let i=0;i<Math.min(f.n,8);i++)drawSprite('flag',W-7-i*6,272,PAL.flag);
}
function drawTitle(){
  txt('GALAGA',112,32,'#ff3030',26);
  txt('HIGH SCORE '+G.hi,112,66,'#ffffff');
  drawSprite('boss',18,88,PAL.boss);
  txt('BOSS GALAGA',42,92,'#ffffff',8,'left');
  txt('150',122,92,'#ffffff',8,'right'); txt('400',148,92,'#ffffff',8,'right');
  txt('800',174,92,'#ffffff',8,'right'); txt('1600',208,92,'#ffffff',8,'right');
  drawSprite('goei',22,112,PAL.goei);
  txt('GOEI',42,116,'#ffffff',8,'left');
  txt('80',148,116,'#ffffff',8,'right'); txt('160',208,116,'#ffffff',8,'right');
  drawSprite('zakoA',23,136,PAL.zako);
  txt('ZAKO',42,140,'#ffffff',8,'left');
  txt('50',148,140,'#ffffff',8,'right'); txt('100',208,140,'#ffffff',8,'right');
  txt('100 FOR EACH HIT IN CHALLENGING STAGE',112,160,'#ffd800',7);
  txt('1ST EXTRA SHIP AT 20,000 PTS',112,172,'#ffd800',7);
  if(Math.floor(G.tick/30)%2)txt('PRESS ENTER TO START',112,205,'#ffffff',9);
  txt('ARROWS/AD MOVE  SPACE FIRE  P PAUSE  M MUTE',112,230,'#808080',7);
}
function drawResults(){
  txt('NUMBER OF SHOTS',64,100,'#ffffff',8,'left');
  txt(String(G.stats.shots),176,100,'#ffffff',8,'left');
  txt('NUMBER OF HITS',64,116,'#ffffff',8,'left');
  txt(String(G.stats.hits),176,116,'#ffffff',8,'left');
  const r=G.stats.shots?Math.round(100*G.stats.hits/G.stats.shots):0;
  txt('HIT-MISS RATIO',64,132,'#ffffff',8,'left');
  txt(r+'%',176,132,'#ffffff',8,'left');
}
function drawChalResult(){
  txt('NUMBER OF HITS',64,100,'#ffffff',8,'left');
  txt(String(G.chal.hits),176,100,'#ffffff',8,'left');
  txt('BONUS',64,116,'#ffffff',8,'left');
  txt(String(G.chal.bonus),176,116,'#ffffff',8,'left');
  if(G.chal.hits===40&&Math.floor(G.tick/15)%2)txt('PERFECT!',112,140,'#ffd800',12);
}
function render(){
  ctx.fillStyle='#000'; ctx.fillRect(0,0,W,H);
  drawStars();
  if(G.state==='title'){drawTitle();return;}
  for(const e of G.enemies)if(e.state==='tractor'&&e.beamT>15)drawBeam(e);
  for(const e of G.enemies)drawEnemy(e);
  if(G.hostile)drawSprite('player',Math.round(G.hostile.x)-6,Math.round(G.hostile.y)-7,PAL.hostile);
  if(G.freed)drawSprite('player',Math.round(G.freed.x)-6,Math.round(G.freed.y)-7,PAL.player);
  drawPlayer();
  ctx.fillStyle='#ffffff';
  for(const b of G.pShots)ctx.fillRect(b.x-1,b.y-3,2,6);
  ctx.fillStyle='#ffe0a0';
  for(const b of G.eBullets)ctx.fillRect(b.x-1,b.y-2,2,4);
  for(const e of G.explosions)drawExplosion(e);
  drawHUD();
  if(G.state==='stageIntro')
    txt(G.challenge?'CHALLENGING STAGE':'STAGE '+G.stage,112,150,'#ffffff',10);
  if(G.state==='play'&&G.readyMsg>0)txt('READY',112,158,'#ff4040',12);
  if(G.state==='gameover')txt('GAME OVER',112,150,'#ff4040',12);
  if(G.state==='results')drawResults();
  if(G.state==='chalResult')drawChalResult();
  if(G.paused)txt('PAUSE',112,130,'#ffff00',12);
  if(G.mute)txt('MUTE',216,6,'#808080',7,'right');
}

/* ---------------- input ---------------- */
addEventListener('keydown',e=>{
  const k=e.key;
  if([' ','Enter','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(k))e.preventDefault();
  initAudio(); /* audio starts on first key press */
  if(e.repeat)return;
  const lk=k.toLowerCase();
  keys[lk]=true;
  if(k==='Enter'&&G.state==='title')startGame();
  if(k===' '&&G.state==='play'&&!G.paused)fire();
  if(lk==='p'&&(G.state==='play'))G.paused=!G.paused;
  if(lk==='m'){G.mute=!G.mute;if(master)master.gain.value=G.mute?0:0.3;}
});
addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false;});

/* ---------------- fixed-timestep main loop ---------------- */
let last=0,acc=0;
function loop(ts){
  requestAnimationFrame(loop);
  if(!last)last=ts;
  acc+=Math.min(ts-last,100); last=ts;
  while(acc>=DT){ if(!G.paused)update(); acc-=DT; }
  render();
}
requestAnimationFrame(loop);
</script>
